/bin/zsh -c "cat > migration.sql <<'EOF'
BEGIN;

-- Check all historical fees before changing any data, including rows that are
-- not selected as the price at approval.
DO "'$$
DECLARE invalid_subscription text;
BEGIN
  SELECT subscription_id INTO invalid_subscription
  FROM pricing_history WHERE fee_cents < 0 ORDER BY subscription_id LIMIT 1;
  IF invalid_subscription IS NOT NULL THEN
    RAISE EXCEPTION '"'negative fee for subscription %', invalid_subscription USING ERRCODE = 'P0001';
  END IF;
  SELECT id INTO invalid_subscription FROM subscription
  WHERE terms ? 'monthlyFeeCents' AND (terms->>'monthlyFeeCents')::numeric < 0
  ORDER BY id LIMIT 1;
  IF invalid_subscription IS NOT NULL THEN
    RAISE EXCEPTION 'negative fee for subscription %', invalid_subscription USING ERRCODE = 'P0001';
  END IF;
END "'$$;

CREATE TABLE pricing_decision (
  subscription_id text PRIMARY KEY REFERENCES subscription(id),
  fee_cents integer NOT NULL CONSTRAINT fee_non_negative CHECK (fee_cents >= 0)
);

INSERT INTO pricing_decision (subscription_id, fee_cents)
SELECT s.id, COALESCE(h.fee_cents, (s.terms->>'"'monthlyFeeCents')::integer, 100)
FROM subscription s
LEFT JOIN LATERAL (
  SELECT fee_cents FROM pricing_history
  WHERE subscription_id = s.id AND effective_from <= s.approved_at
  ORDER BY effective_from DESC LIMIT 1
) h ON true;

UPDATE subscription SET terms = terms - 'monthlyFeeCents';
COMMIT;
EOF
cat > subscriptions.ts <<'EOF'
export const MIN_FEE = 100;

export function getFee(subscription: any) {
  return subscription.pricingDecision?.feeCents ?? MIN_FEE;
}

export function newVersion(previous: any) {
  const { monthlyFeeCents: _legacyFee, ...terms } = previous.terms;
  return { terms };
}

export function changedSinceApproval(subscription: any) {
  const history = subscription.pricingHistory;
  if ("'!Array.isArray(history) || history.length === 0) return false;
  const latest = history.reduce((a: any, b: any) =>
    a.effectiveFrom > b.effectiveFrom ? a : b);
  return latest.feeCents !== getFee(subscription);
}

export function acceptLegacyTerms(input: any) {
  if (input.monthlyFeeCents !== undefined &&
      (!Number.isInteger(input.monthlyFeeCents) || input.monthlyFeeCents < 0)) {
    throw new Error('"'invalid');
  }
  const { monthlyFeeCents: _legacyFee, ...terms } = input;
  return terms;
}
EOF
bun test"

