/bin/zsh -c "cat > smoke.test.ts <<'EOF'
import { test, expect } from 'bun:test';
import { acceptLegacyTerms, changedSinceApproval, getFee, newVersion } from './subscriptions';

test('approved decision and default fee', () => {
  expect(getFee({ pricingDecision: { feeCents: 2500 } })).toBe(2500);
  expect(getFee({})).toBe(100);
});

test('new versions and legacy input do not carry an old fee decision', () => {
  const previous = { terms: { monthlyFeeCents: 2500, name: 'plan' }, pricingDecision: { feeCents: 2500 } };
  expect(newVersion(previous)).toEqual({ terms: { name: 'plan' } });
  expect(acceptLegacyTerms(previous.terms)).toEqual({ name: 'plan' });
  expect(() => acceptLegacyTerms({ monthlyFeeCents: -1 })).toThrow();
  expect(previous.terms.monthlyFeeCents).toBe(2500);
});

test('detects a later price change against the approved decision', () => {
  expect(changedSinceApproval({ pricingDecision: { feeCents: 2500 }, pricingHistory: [
    { effectiveFrom: '2024-02-01', feeCents: 3000 },
    { effectiveFrom: '2024-01-01', feeCents: 2500 },
  ] })).toBe(true);
  expect(changedSinceApproval({ pricingDecision: { feeCents: 2500 }, pricingHistory: [
    { effectiveFrom: '2024-01-01', feeCents: 2500 },
  ] })).toBe(false);
});
EOF
bun test"

